source.admin-queue.th:
function theadHtml() {
  var h = "";
  COLS.forEach(function (c) {
    if (c.relleno) { h += '<th class="cnt-th" data-col="relleno" aria-hidden="true"></th>'; return; }
    var on = STATE.sort.key === c.key;
    var flecha = '<span class="queue-arrow" aria-hidden="true">' + (on ? (STATE.sort.dir === 1 ? "▲" : "▼") : "") + "</span>";
    var label = esc(c.label);
    // scope + aria-sort: el lector nombra la columna al leer cada celda y
    // dice por cuál está ordenada la tabla, en vez de leer una flecha suelta.
    var sort = on ? (STATE.sort.dir === 1 ? "ascending" : "descending") : "none";
    // tabindex: ordenar tiene que poder hacerse con el teclado, no sólo con
    // el mouse (el delegado de keydown de más abajo escucha Enter/Espacio).
    h += '<th scope="col" aria-sort="' + sort + '" tabindex="0" class="cnt-th cnt-th-sortable' + (on ? " on" : "")
      + '" data-col="' + c.key + '" data-cola-sort="' + c.key + '"'
      + ' title="' + esc(applyVars(T("admin.queue.table.ordenar_por", { label: c.label }, "Ordenar por {label}"), { label: c.label })) + '">' + label + flecha + "</th>";
  });
  return h;
}

source.admin-patients.thead:
function paintTable() {
  var activas = activeCols();
  var thead = "", i;
  for (i = 0; i < activas.length; i++) {
    var c = activas[i], on = c.key === ORDEN.key;
    var aria = on ? (ORDEN.dir === 1 ? "ascending" : "descending") : "none";
    thead += '<th scope="col" data-col="' + esc(c.key) + '" data-sort="' + esc(c.key)
      + '" aria-sort="' + aria + '" tabindex="0" class="cnt-th' + (c.numeric ? " cnt-numeric" : "") + ' cnt-th-sortable' + (on ? " on" : "") + '">'
      + esc(c.label) + (on ? (ORDEN.dir === 1 ? " ▲" : " ▼") : "") + "</th>";
  }

source.admin-users.theadHtml:
function theadHtml(activas, SORT) {
  return activas.map(function (c) {
    return '<th scope="col" class="cnt-th cnt-th-sortable" data-sort="' + esc(c.key)
      + '" tabindex="0" aria-sort="' + (SORT.key === c.key ? (SORT.dir === 1 ? "ascending" : "descending") : "none")
      + '">' + esc(c.label) + "</th>";
  }).join("");
}

source.admin-content.catalog-th:
var sortable = n > 10;

var s = SORT[tipo];
var col = cols.filter(function (c) { return c.key === s.key; })[0] || cols[0];
var q = SEARCH[tipo];
var visible = items.filter(function (it) { return matchesSearch(tipo, it, q, cols); });
if (tipo === "medicos") visible = visible.filter(matchesFiltrosMed);
if (tipo === "servicios") visible = visible.filter(matchesFiltrosServicios);
visible.sort(function (a, b) { return compararCol(col, a, b, s.dir); });
// A blank trailing column is only useful when it contains a row action.
// Restore is the sole list-row action, and only administrators can use it.
var hasRowActions = puedeAltaBaja(tipo) && visible.some(function (it) { return !!it._borrado; });

var theadRow = $("#cnt-thead-" + tipo, sec);
var theadHtml = "";
if (tipo === "medicos" && puede("usuarios")) {
  theadHtml += '<th class="cnt-th cnt-th-check"><input type="checkbox" id="med-select-all" aria-label="' + esc(T("admin.content.catalog.list.select_visible_doctors", null, "Seleccionar médicos visibles")) + '"></th>';
}
cols.forEach(function (c) {
  var on = c.key === s.key;
  theadHtml += '<th data-col="' + esc(c.key) + '"' + (sortable ? ' data-sort="' + c.key + '" class="cnt-th' + (c.numeric ? " cnt-numeric" : "") + ' cnt-th-sortable' + (on ? " on" : "") + '"' : ' class="cnt-th' + (c.numeric ? " cnt-numeric" : "") + '"') +
    ">" + esc(c.label) + (on ? (s.dir === 1 ? " ▲" : " ▼") : "") + "</th>";
});
if (hasRowActions) theadHtml += '<th class="cnt-th cnt-th-acts"></th>';
theadRow.innerHTML = theadHtml;

source.admin-content.medcal-th:
var sortable = turnos.length > 3;
function th(label, key) {
  if (!sortable) return '<th class="cnt-th">' + label + "</th>";
  var active = sort && sort.key === key;
  return '<th class="cnt-th"><button type="button" class="medcal-sort" data-med-sort="' + key + '" data-dia="' + esc(diaIso) + '">' + label + (active ? (sort.dir === "asc" ? " ↑" : " ↓") : "") + "</button></th>";
}

source.admin-solicitudes.colsHtml:
function colsHtml(cols, sort) {
  var out = '<div class="sol-cols" style="grid-template-columns:' + gridFor(cols) + '"><div></div>';
  cols.forEach(function (c) {
    var on = sort && sort.key === c.key;
    var arrow = "sol-sar " + (on ? (sort.dir > 0 ? "sol-sar-u" : "sol-sar-d") : "sol-sar-off");
    var cls = "sol-ch sol-ch-" + c.key + (c.right ? " sol-ch-r" : "") + (on ? " sol-ch-on" : "");
    var label = esc(c.label);
    var ariaLabel = esc(T("admin.queue.table.ordenar_por", { label: c.label }, "Ordenar por " + c.label));
    var caret = '<span class="' + arrow + '"></span>';
    var labelSpan = '<span class="sol-ch-t">' + label + "</span>";
    out += '<button type="button" class="' + cls + '" data-sol-sort="' + esc(c.key) + '"'
      + ' aria-label="' + ariaLabel + '">'
      + (c.right ? caret + labelSpan : labelSpan + caret) + "</button>";
  });
  return out + "</div>";
}
